// Decide si hay que rescatar el dia de hoy.
// Devuelve un item solo cuando hay pieza programada y NO esta publicada.
// Si no hay nada que hacer, devuelve [] y el flujo termina en silencio.

const hoy = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Madrid' });

let registro, calendario;
try {
  registro = JSON.parse($('Leer registro').first().json.cuerpo);
} catch (e) {
  throw new Error('registro.json no se pudo interpretar: ' + e.message);
}
try {
  calendario = JSON.parse($('Leer calendario').first().json.cuerpo);
} catch (e) {
  throw new Error('calendario.json no se pudo interpretar: ' + e.message);
}

const pieza = calendario[hoy];

if (!pieza) {
  // No hay pieza programada para hoy (fin de semana sin contenido, calendario agotado).
  // No es un fallo: no se dispara nada.
  return [];
}

if (registro[hoy]) {
  // El cron de GitHub ya publico. Nada que hacer.
  return [];
}

return [{
  json: {
    fecha: hoy,
    dia: pieza.dia ?? null,
    tema: pieza.tema ?? '(sin tema en el calendario)',
    motivo: 'Hay pieza programada y el registro no la tiene. El cron de GitHub no ha llegado.'
  }
}];

